import SwiftUI
import WebKit

struct PadPanelLogoView: View {
    var size: CGSize = CGSize(width: 130, height: 78)
    var tintColor: Color = .white

    var body: some View {
        Group {
            if let _ = UIImage(named: "PadPanelLogo") {
                Image("PadPanelLogo")
                    .resizable()
                    .renderingMode(.template)
                    .aspectRatio(contentMode: .fit)
                    .foregroundColor(tintColor)
            } else {
                // Vector SVG WebKit Renderer for crisp Retina rendering
                SVGVectorView()
            }
        }
        .frame(width: size.width, height: size.height)
    }
}

